/**
 * Public product UI captures used on the marketing site.
 * Source masters live in docs/collateral/screenshots/ — keep filenames aligned.
 *
 * All present-tense captions describe shipped product surface, not roadmap,
 * and each caption is used ONCE across the site (the redesign's no-duplicate
 * rule). Blur placeholders are generated from the masters so frames paint
 * instantly while the optimizer serves the real image.
 */
export type ProductScreen = {
  id: string;
  src: `/images/product/${string}`;
  title: string;
  caption: string;
  alt: string;
  /** Short label for thumbnails / chips */
  label: string;
  blurDataURL: string;
};

